/* ==========================================================================
   Volta Studio — Global Styles
   Minimal, editorial, warm.
   ========================================================================== */

/* --- Reset & Base --- */
*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --bg: #F5F2ED;
  --text: #1A1A1A;
  --text-light: #6B6560;
  --accent-terracotta: #C4826E;
  --accent-sage: #9EAF8E;
  --accent-sand: #D4C5A9;
  --serif: 'Playfair Display', Georgia, 'Times New Roman', serif;
  --sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
  --max-width: 1280px;
  --page-padding: clamp(24px, 5vw, 80px);
}

html {
  font-size: 16px;
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  background-color: var(--bg);
  color: var(--text);
  font-family: var(--sans);
  font-weight: 400;
  line-height: 1.65;
  overflow-x: hidden;
}

a {
  color: inherit;
  text-decoration: none;
}

img {
  max-width: 100%;
  display: block;
}

/* --- Header --- */
.site-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 28px var(--page-padding);
  position: fixed;
  top: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background-color: var(--bg);
}

.logo {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}

.desktop-nav {
  display: flex;
  gap: 36px;
}

.desktop-nav a {
  font-size: 0.9rem;
  font-weight: 400;
  letter-spacing: 0.01em;
  transition: opacity 0.2s ease;
}

.desktop-nav a:hover,
.desktop-nav a.active {
  opacity: 0.5;
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  gap: 6px;
  background: none;
  border: none;
  cursor: pointer;
  width: 32px;
  height: 32px;
  position: relative;
  z-index: 200;
}

.hamburger span {
  display: block;
  width: 24px;
  height: 2px;
  background-color: var(--text);
  transition: transform 0.3s ease, opacity 0.3s ease;
}

.hamburger.is-open span:first-child {
  transform: translateY(4px) rotate(45deg);
}

.hamburger.is-open span:last-child {
  transform: translateY(-4px) rotate(-45deg);
}

/* Mobile Menu */
.mobile-menu {
  position: fixed;
  inset: 0;
  background-color: var(--bg);
  z-index: 150;
  display: flex;
  align-items: center;
  justify-content: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s ease, visibility 0.35s ease;
}

.mobile-menu.is-open {
  opacity: 1;
  visibility: visible;
}

.mobile-nav {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 32px;
}

.mobile-nav a {
  font-family: var(--serif);
  font-size: 2.5rem;
  font-weight: 700;
  transition: opacity 0.2s ease;
}

.mobile-nav a:hover {
  opacity: 0.5;
}

@media (max-width: 768px) {
  .desktop-nav {
    display: none;
  }
  .hamburger {
    display: flex;
  }
}

/* ==========================================================================
   Homepage
   ========================================================================== */

/* --- Hero --- */
.hero {
  padding: 180px var(--page-padding) 80px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.hero-title {
  font-family: var(--serif);
  font-size: clamp(2.5rem, 6vw, 5.5rem);
  font-weight: 900;
  line-height: 1.08;
  letter-spacing: -0.025em;
  max-width: 900px;
}

/* --- Media Showcase --- */
.media-showcase {
  padding: 0 var(--page-padding) 100px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.media-triptych {
  display: grid;
  grid-template-columns: 1fr 1fr 1fr;
  gap: 16px;
}

.media-block {
  aspect-ratio: 4 / 5;
  border-radius: 4px;
}

@media (max-width: 640px) {
  .media-triptych {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .media-block {
    aspect-ratio: 16 / 9;
  }
}

/* --- Client Marquee --- */
.client-marquee {
  padding: 60px 0;
  overflow: hidden;
  border-top: 1px solid rgba(26, 26, 26, 0.1);
  border-bottom: 1px solid rgba(26, 26, 26, 0.1);
}

.marquee-row {
  overflow: hidden;
  white-space: nowrap;
  padding: 12px 0;
}

.marquee-track {
  display: inline-flex;
  align-items: center;
  gap: 0;
  will-change: transform;
}

.marquee-track span {
  font-family: var(--serif);
  font-size: clamp(1.5rem, 3.5vw, 3rem);
  font-weight: 700;
  letter-spacing: -0.01em;
  padding: 0 16px;
  flex-shrink: 0;
}

.marquee-track .sep {
  font-size: clamp(0.8rem, 1.5vw, 1.2rem);
  opacity: 0.3;
  padding: 0 8px;
}

.marquee-left .marquee-track {
  animation: scroll-left 30s linear infinite;
}

.marquee-right .marquee-track {
  animation: scroll-right 30s linear infinite;
}

@keyframes scroll-left {
  0% { transform: translateX(0); }
  100% { transform: translateX(-50%); }
}

@keyframes scroll-right {
  0% { transform: translateX(-50%); }
  100% { transform: translateX(0); }
}

/* --- About --- */
.about {
  padding: 120px var(--page-padding);
  max-width: var(--max-width);
  margin: 0 auto;
}

.about-inner {
  display: grid;
  grid-template-columns: 200px 1fr;
  gap: 60px;
  align-items: start;
}

.about-label {
  font-size: 0.8rem;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: 0.1em;
  color: var(--text-light);
  padding-top: 6px;
}

.about-text p {
  font-size: 1.15rem;
  line-height: 1.75;
  margin-bottom: 24px;
  max-width: 680px;
}

.about-text p:last-child {
  margin-bottom: 0;
}

@media (max-width: 768px) {
  .about-inner {
    grid-template-columns: 1fr;
    gap: 24px;
  }
}

/* ==========================================================================
   Founder Letter (neweno.html)
   ========================================================================== */

.founder-letter {
  padding: 180px var(--page-padding) 120px;
  max-width: 780px;
  margin: 0 auto;
}

.letter-header {
  margin-bottom: 80px;
}

.letter-title {
  font-family: var(--serif);
  font-size: clamp(2.8rem, 5.5vw, 4.5rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.025em;
}

.letter-body p {
  font-size: 1.15rem;
  line-height: 1.8;
  margin-bottom: 28px;
}

.letter-greeting {
  font-family: var(--serif);
  font-size: 1.5rem;
  font-weight: 700;
  line-height: 1.4;
  margin-bottom: 32px !important;
}

.letter-pullquote {
  margin: 56px 0;
  padding-left: 32px;
  border-left: 3px solid var(--accent-terracotta);
}

.letter-pullquote p {
  font-family: var(--serif);
  font-size: 1.4rem;
  font-style: italic;
  line-height: 1.6;
  color: var(--text);
  margin-bottom: 0;
}

.letter-sign-off {
  font-family: var(--serif);
  font-size: 2rem;
  font-weight: 900;
  font-style: italic;
  margin-top: 48px !important;
  margin-bottom: 48px !important;
}

.letter-signature {
  font-size: 1rem;
  line-height: 1.6;
  margin-top: 60px !important;
}

.sig-role {
  color: var(--text-light);
  font-size: 0.9rem;
}

/* ==========================================================================
   Services (services.html)
   ========================================================================== */

.philosophy {
  padding: 180px var(--page-padding) 100px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.philosophy-title {
  font-family: var(--serif);
  font-size: clamp(2.8rem, 5.5vw, 4.5rem);
  font-weight: 900;
  line-height: 1.1;
  letter-spacing: -0.025em;
  margin-bottom: 48px;
}

.philosophy-body {
  max-width: 680px;
}

.philosophy-body p {
  font-size: 1.15rem;
  line-height: 1.8;
  margin-bottom: 24px;
}

.philosophy-body em {
  font-style: italic;
}

.section-divider {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 var(--page-padding);
  height: 1px;
  position: relative;
}

.section-divider::after {
  content: '';
  display: block;
  height: 1px;
  background-color: rgba(26, 26, 26, 0.12);
}

.service-details {
  padding: 100px var(--page-padding) 120px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.services-question {
  font-family: var(--serif);
  font-size: clamp(1.8rem, 3.5vw, 2.8rem);
  font-weight: 700;
  line-height: 1.2;
  letter-spacing: -0.02em;
  margin-bottom: 64px;
  max-width: 600px;
}

.service-item {
  margin-bottom: 56px;
  max-width: 680px;
}

.service-item:last-child {
  margin-bottom: 0;
}

.service-name {
  font-family: var(--serif);
  font-size: 1.6rem;
  font-weight: 700;
  margin-bottom: 16px;
}

.service-item p {
  font-size: 1.05rem;
  line-height: 1.8;
  color: var(--text);
}

/* ==========================================================================
   Clients (clients.html)
   ========================================================================== */

.clients-heading {
  padding: 180px var(--page-padding) 40px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.clients-title {
  font-family: var(--serif);
  font-size: clamp(3rem, 6vw, 5.5rem);
  font-weight: 900;
  line-height: 1.05;
  letter-spacing: -0.03em;
}

.clients-subtitle {
  font-size: 1.1rem;
  color: var(--text-light);
  margin-top: 12px;
}

.clients-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 48px 40px;
  padding: 60px var(--page-padding) 120px;
  max-width: var(--max-width);
  margin: 0 auto;
}

.client-card h3 {
  font-family: var(--serif);
  font-size: 1.35rem;
  font-weight: 700;
  margin-bottom: 8px;
}

.client-card p {
  font-size: 0.95rem;
  line-height: 1.7;
  color: var(--text-light);
}

@media (max-width: 900px) {
  .clients-grid {
    grid-template-columns: repeat(2, 1fr);
  }
}

@media (max-width: 560px) {
  .clients-grid {
    grid-template-columns: 1fr;
    gap: 40px;
  }
}

/* ==========================================================================
   Contact (contact.html)
   ========================================================================== */

.contact-hero {
  min-height: 100vh;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: var(--page-padding);
  text-align: center;
}

.contact-title {
  font-family: var(--serif);
  font-size: clamp(5rem, 15vw, 14rem);
  font-weight: 900;
  line-height: 1;
  letter-spacing: -0.04em;
  margin-bottom: 48px;
}

.contact-links {
  display: flex;
  gap: 40px;
}

.contact-link {
  font-size: 1.1rem;
  font-weight: 400;
  transition: opacity 0.2s ease;
  position: relative;
}

.contact-link::after {
  content: '';
  position: absolute;
  bottom: -2px;
  left: 0;
  width: 0;
  height: 1px;
  background-color: var(--text);
  transition: width 0.3s ease;
}

.contact-link:hover::after {
  width: 100%;
}

.contact-link:hover {
  opacity: 0.6;
}

@media (max-width: 480px) {
  .contact-links {
    flex-direction: column;
    gap: 20px;
  }
}

/* ==========================================================================
   Footer
   ========================================================================== */

.site-footer {
  padding: 40px var(--page-padding);
  text-align: center;
  font-size: 0.8rem;
  color: var(--text-light);
  border-top: 1px solid rgba(26, 26, 26, 0.08);
}

