  gap: 16px;
}

.media-block {
  aspect-ratio: 4 / 5;
  border-radius: 4px;
}

@media (max-width: 640px) {
  .media-triptych {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .media-block {
    aspect-ratio: 16 / 9;
  }
}

/* --- Client Marquee --- */
.client-marquee {
  padding: 60px 0;
